// Production catalogを隔離PostgreSQLへ再構成。Native adapterはloopback専用。外部DBへ接続しない。
import fs from 'node:fs';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
const sha=s=>createHash('sha256').update(s).digest('hex');
const modulePath=process.env.RAID_PGLITE_MODULE;
if(!modulePath) throw new Error('RAID_PGLITE_MODULEにPGlite 0.5.8のローカルentryを指定してください');
const {PGlite}=await import(pathToFileURL(path.resolve(modulePath)).href);
const db=new PGlite();
const dir='docs/development/raid-production-preparation/audit-a';
const c=JSON.parse(fs.readFileSync(`${dir}/catalog.json`,'utf8'));
const quote=s=>'"'+s.replaceAll('"','""')+'"';
const result={engine:process.env.RAID_REHEARSAL_ENGINE||'PGlite 0.5.8 / in-memory only',limitations:['空データから列・制約・関数・triggerを再構成。実ユーザーはコピーしない。','AuthはGUC参照stub。Cronは実行しない。複数接続・Edge・UI受入ではない。'],steps:[]};
try {
 if(process.env.RAID_REHEARSAL_ENGINE)await db.exec("do $$ begin if not exists(select from pg_roles where rolname='postgres') then create role postgres superuser; end if; end $$; set role postgres;");
 await db.exec(`do $$ begin if not exists(select from pg_roles where rolname='anon') then create role anon; end if; if not exists(select from pg_roles where rolname='authenticated') then create role authenticated; end if; if not exists(select from pg_roles where rolname='service_role') then create role service_role; end if; end $$;
 create schema auth; create table auth.users(id uuid primary key,created_at timestamptz default now(),is_anonymous boolean default true);
 create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
 create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
 create function auth.role() returns text language sql stable as $$select current_setting('request.jwt.claim.role',true)$$;
 set check_function_bodies=off;`);
 result.serverVersion=(await db.query('select version() value')).rows[0].value;
 const seqs=new Set(c.columns.flatMap(x=>[...(x.default??'').matchAll(/nextval\('([^']+)'/g)].map(m=>m[1])));
 for(const s of seqs) await db.exec(`create sequence ${s};`);
 for(const r of c.relations.filter(r=>r.kind!=='v')){
   const columns=c.columns.filter(x=>x.table===r.name);
   await db.exec(`create table public.${quote(r.name)} (${columns.map(x=>`${quote(x.column)} ${x.type}${x.identity?(x.identity==='a'?' generated always as identity':' generated by default as identity'):x.generated?` generated always as (${x.default}) stored`:x.default?` default ${x.default}`:''}${x.not_null?' not null':''}`).join(',')});`);
 }
 for(const f of c.functions.filter(f=>f.definition)) await db.exec(f.definition+';');
 for(const v of JSON.parse(fs.readFileSync(dir+'/views.json','utf8')))await db.exec('create view public.'+quote(v.name)+(v.options?.length?' with ('+v.options.join(',')+')':'')+' as '+v.definition);
 for(const con of c.constraints.filter(x=>!x.definition.startsWith('FOREIGN KEY'))) await db.exec(`alter table public.${quote(con.table)} add constraint ${quote(con.name)} ${con.definition};`);
 for(const con of c.constraints.filter(x=>x.definition.startsWith('FOREIGN KEY'))) await db.exec(`alter table public.${quote(con.table)} add constraint ${quote(con.name)} ${con.definition};`);
 for(const idx of c.indexes.filter(x=>!c.constraints.some(k=>k.name===x.indexname))) await db.exec(idx.indexdef+';');
 for(const t of c.triggers.filter(t=>c.functions.some(f=>f.definition&&t.function.split('(')[0].replace('public.','')===f.name))) await db.exec(t.definition+';');

 const privilege={a:'INSERT',r:'SELECT',w:'UPDATE',d:'DELETE',D:'TRUNCATE',x:'REFERENCES',t:'TRIGGER',m:'MAINTAIN',X:'EXECUTE'};
 const restoreAcl=async(target,acl)=>{if(!acl)return;await db.exec('revoke all on '+target+' from public,anon,authenticated,service_role,postgres');for(const entry of acl){const m=entry.match(/^([^=]*)=([^/]+)\/[^/]+$/);if(!m)throw Error('Unexpected ACL '+entry);const role=m[1]?quote(m[1]):'public';const permissions=[...m[2]].map(c=>privilege[c]);if(permissions.some(x=>!x))throw Error('Unsupported ACL '+entry);await db.exec('grant '+permissions.join(',')+' on '+target+' to '+role);}};
 for(const f of c.functions)await restoreAcl('function public.'+quote(f.name)+'('+f.args+')',f.acl);
 for(const r of c.relations){if(r.rls)await db.exec('alter table public.'+quote(r.name)+' enable row level security');if(r.force_rls)await db.exec('alter table public.'+quote(r.name)+' force row level security');await restoreAcl('table public.'+quote(r.name),r.acl);}
 for(const p of c.policies)await db.exec('create policy '+quote(p.policyname)+' on public.'+quote(p.tablename)+' as '+p.permissive+' for '+p.cmd+' to '+p.roles.map(x=>x==='public'?'public':quote(x)).join(',')+(p.qual?' using ('+p.qual+')':'')+(p.with_check?' with check ('+p.with_check+')':''));
 await db.exec('create schema cron;create table cron.job(jobid bigint,jobname text,schedule text,command text,active boolean,database text,username text);create schema supabase_migrations;create table supabase_migrations.schema_migrations(version text,name text);');
 for(const j of c.cron)await db.query('insert into cron.job values($1,$2,$3,$4,$5,$6,$7)',[j.jobid,j.jobname,j.schedule,j.command,j.active,j.database,j.username]);
 for(const m of c.migrations)await db.query('insert into supabase_migrations.schema_migrations values($1,$2)',[m.version,m.name]);
 await db.exec('set check_function_bodies=on;');
 const beforeFunctions=(await db.query("select proname,pg_get_function_identity_arguments(oid) args,md5(pg_get_functiondef(oid)) hash,proacl from pg_proc where pronamespace='public'::regnamespace and prokind='f' order by 1,2")).rows;
 result.steps.push({name:'catalog reconstruction',status:'PASS',tables:c.relations.length,functions:c.functions.filter(f=>f.definition).length});


 const files=process.argv.slice(2); if(!files.length)throw Error('Pass immutable bundle SQL paths in dependency order');
 result.catalog={observedAt:c.observed_at,projectRef:c.project_ref,sha256:sha(fs.readFileSync(dir+'/catalog.json'))};
 result.inputs=files.map(file=>({file,sha256:sha(fs.readFileSync(file))}));
 result.artifacts=['00-baseline-guard.sql','03-expiry-cron.sql','04-postflight.sql','05-stop-new-operations.sql','review-apply.psql','SHA256SUMS'].map(file=>({file,sha256:sha(fs.readFileSync('docs/development/raid-production-preparation/bundle/'+file))}));
 result.viewsSha256=sha(fs.readFileSync(dir+'/views.json'));
 const sql=files.map(file=>fs.readFileSync(file,'utf8'));
 const allowed=new Set(sql.flatMap(s=>[...s.matchAll(/create\s+or\s+replace\s+function\s+public\.([a-z0-9_]+)/gi)].map(m=>m[1])));
 const snapshot=()=>db.query("select proname,pg_get_function_identity_arguments(oid) args,md5(pg_get_functiondef(oid)) hash,proacl from pg_proc where pronamespace='public'::regnamespace and prokind='f' order by 1,2").then(x=>x.rows);
 await db.exec('begin;');
 const probe=async(file)=>{await db.exec('savepoint guard_probe');try{await db.exec(fs.readFileSync(file,'utf8'));result.steps.push({name:file,status:'PASS',unmodified:true});}catch(e){result.steps.push({name:file,status:'BLOCKED_IN_RECONSTRUCTION',unmodified:true,error:e.message});}finally{await db.exec('rollback to guard_probe; release guard_probe');}};
 await probe('docs/development/raid-production-preparation/bundle/00-baseline-guard.sql');
 for(let i=0;i<files.length;i++){await db.exec(sql[i]);result.steps.push({name:files[i],status:'PASS',unmodified:true});}
 await probe('docs/development/raid-production-preparation/bundle/04-postflight.sql');
 const afterFunctions=await snapshot();
 const protectedFunctions=beforeFunctions.filter(f=>!allowed.has(f.proname));
 for(const f of protectedFunctions)assert.deepEqual(afterFunctions.find(a=>a.proname===f.proname&&a.args===f.args),f);
 result.steps.push({name:'Existing non-target function bodies and reconstructed ACL unchanged',status:'PASS',count:protectedFunctions.length});
 for(const table of ['raid_room_creation_settings','raid_room_battle_settings','raid_room_rescue_settings'])assert.equal((await db.query('select enabled from '+table)).rows[0].enabled,false);
 assert.equal((await db.query('select enabled from raid_legacy_settings')).rows[0].enabled,true);
 for(const table of ['raid_room_clear_reward_rules','raid_room_rescue_reward_rules'])assert.equal((await db.query('select count(*)::int n from '+table+' where enabled')).rows[0].n,0);
 assert.equal((await db.query("select count(*)::int n from pg_class where relnamespace='public'::regnamespace and relname like 'raid_room%' and relkind='r' and not relrowsecurity")).rows[0].n,0);
 result.steps.push({name:'Safe default flags, rewards disabled, new room RLS',status:'PASS'});
 await db.exec('rollback;'); assert.deepEqual(await snapshot(),beforeFunctions);
 assert.equal((await db.query("select to_regclass('public.raid_rooms') value")).rows[0].value,null);
 result.steps.push({name:'Atomic rollback restores every reconstructed function and removes new Room schema',status:'PASS'});

 if(process.env.RAID_REHEARSAL_ENGINE){
 const psql=(file,commit)=>{const r=spawnSync('C:/Program Files/PostgreSQL/17/bin/psql.exe',['-X','-h','127.0.0.1','-p','55462','-U','raid_top_local','-d',db.database,'-v','ON_ERROR_STOP=1','-v','raid_commit='+commit,'-f',file],{encoding:'utf8',env:{...process.env,PGOPTIONS:'-c role=postgres'}});fs.writeFileSync('docs/development/raid-production-preparation/rehearsal/'+path.basename(file)+'.commit-'+commit+'.log',r.stdout+r.stderr);assert.equal(r.status,0,r.stderr);result.steps.push({name:'native psql '+file+' raid_commit='+commit,status:'PASS',unmodified:true,sha256:sha(fs.readFileSync(file))});};
 psql('docs/development/raid-production-preparation/bundle/review-apply.psql',false);assert.deepEqual(await snapshot(),beforeFunctions);
 psql('docs/development/raid-production-preparation/bundle/review-apply.psql',true);
 const counts=async()=> (await db.query("select jsonb_build_object('rooms',(select count(*) from raid_rooms),'replays',(select count(*) from battle_replay_sessions),'presents',(select count(*) from presents),'cron',(select jsonb_agg(to_jsonb(j) order by jobid) from cron.job j)) value")).rows[0].value;
 const preStop=await counts();
 psql('docs/development/raid-production-preparation/bundle/05-stop-new-operations.sql',true);
 for(const t of ['raid_room_creation_settings','raid_room_battle_settings','raid_room_rescue_settings','raid_legacy_settings'])assert.equal((await db.query('select enabled from '+t)).rows[0].enabled,false);
 assert.deepEqual(await counts(),preStop);result.steps.push({name:'Post-stage forward stop persists 4 false flags and preserves existing row counts/Cron metadata',status:'PASS',scope:'empty user data; pending replay continuation separately tested in 17-case fixture'});
 result.database=db.database;
 }
 result.status='PARTIAL_PASS';
 console.log(JSON.stringify(result,null,2));
} catch(e){result.status='FAIL';result.error={message:e.message,where:e.where};console.error(JSON.stringify(result,null,2));process.exitCode=1;}finally{fs.writeFileSync('docs/development/raid-production-preparation/rehearsal/production-bundle-result.json',JSON.stringify(result,null,2)+'\n');await db.close();}
